// GraphRAG Hybrid Retrieval PoC
import { qdrantClient } from './qdrant-client';
import { db } from '../database_service';
import { knowledgeNodes, knowledgeEdges } from '@shared/schema';
import { eq, inArray } from 'drizzle-orm';

export async function hybridRetrieve(query: string, topicId: number, options: { maxHops?: number; topK?: number } = {}) {
  const { maxHops = 2, topK = 10 } = options;

  // Stage 1: Vector similarity search for seed entities
  const vectorResults = await qdrantClient.search(topicId, query, { limit: topK });
  const seedNodeIds = vectorResults.map(r => r.payload.nodeId).filter(Boolean);

  // Stage 2: Graph traversal from seed entities
  const graphResults = await traverseGraph(seedNodeIds, maxHops);

  // Stage 3: Reciprocal Rank Fusion merge
  return reciprocalRankFusion(vectorResults, graphResults, topK);
}

async function traverseGraph(seedIds: number[], maxHops: number) {
  let currentLayer = seedIds;
  const visited = new Set(seedIds);
  const results: any[] = [];

  for (let hop = 0; hop < maxHops; hop++) {
    const edges = await db.select().from(knowledgeEdges)
      .where(inArray(knowledgeEdges.sourceId, currentLayer));
    const nextLayer: number[] = [];
    for (const edge of edges) {
      if (!visited.has(edge.targetId)) {
        visited.add(edge.targetId);
        nextLayer.push(edge.targetId);
        results.push({ nodeId: edge.targetId, hop: hop + 1, relation: edge.relationType });
      }
    }
    currentLayer = nextLayer;
  }
  return results;
}
